import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,o as a,c as s,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Bluetooth Settings","description":"","frontmatter":{},"headers":[],"relativePath":"use/bluetooth.md","filePath":"use/bluetooth.md"}'),r={name:"use/bluetooth.md"};function c(d,t,p,u,h,m){return a(),s("div",null,[...t[0]||(t[0]=[l('<p>The number of Android phone manufacturers and sensor/bridge particularities has made Bluetooth connection reliability a major difficulty for xDrip. This menu contains a lot of deep settings that cannot be standardized for all systems.</p><div class="info custom-block"><p class="custom-block-title">Set up Bluetooth settings as shown below</p></div><p>Trial and error approach is recommended, but change only one setting at a time to avoid further confusion.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Settings<br>  Less common settings<br>   <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Bluetooth Settings</p></div><h4 id="turn-bluetooth-on" tabindex="-1">Turn Bluetooth On <a class="header-anchor" href="#turn-bluetooth-on" aria-label="Permalink to &quot;Turn Bluetooth On&quot;">​</a></h4><p>This option will make xDrip try to enable Bluetooth.</p><p>If xDrip is connecting to a Bluetooth device, Turn Bluetooth on is mandatory.<br> xDrip might not be able to fully override your phone settings, meaning that if you disable Bluetooth in Android settings or put your phone in airplane mode it might not be able to turn it on. Bluetooth must be enabled in Android settings if you want xDrip to use it.</p><p><em>Collector: Global BT handling (classic bridge + OB1 Dex) — Dexcom G5/G6/G7, G4/Libre bridges</em></p><div class="admonition xdripitem"><p class="admonition-title">Turn Bluetooth on<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Automatically enable Bluetooth if it is switched off when we try to connect to a Bluetooth device</p></div><h4 id="bluetooth-watchdog" tabindex="-1">Bluetooth Watchdog <a class="header-anchor" href="#bluetooth-watchdog" aria-label="Permalink to &quot;Bluetooth Watchdog&quot;">​</a></h4><p>In case of missing data due to Bluetooth connection loss, you can make xDrip switch your phone Bluetooth off then on; the default timing is 20 minutes without data. You can customize this value.</p><p>If you see the message that <strong>xDrip turned off Bluetooth</strong> this is probably because the watchdog triggered and xDrip is trying to recover connection with the sensor.</p><p><em>Collector: Global recovery logic (classic + sequencer collectors) — Dexcom &amp; bridge-based collectors</em></p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Watchdog<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Reset Bluetooth by turning it off and on if we don&#39;t get anything in 20 minutes</p></div><p>When the watchdog is enabled, you can choose after how long without data it triggers: 20 (default), 15, 10 or 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Timer value for BT watchdog</p><p> Input value in minutes</p></div><div class="info custom-block"><p class="custom-block-title">Info</p><p>Mind the Bluetooth watchdog activating will lead to a temporary Bluetooth disconnection on all connected devices. You might want to disable this feature if you use AAPS and your bridge/pump doesn&#39;t automatically recover Bluetooth connection.<br> Note that the Dexcom collector (G5/G6/G7/ONE/ONE+/Stelo) has its own Bluetooth watchdog, always active and not controlled by this setting (the Dex Bluetooth Watchdog setting was removed in <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.04.22" target="_blank" rel="noreferrer">2026.04.22</a>).</p></div><h4 id="close-gatt-on-ble-disconnect" tabindex="-1">Close GATT on BLE disconnect <a class="header-anchor" href="#close-gatt-on-ble-disconnect" aria-label="Permalink to &quot;Close GATT on BLE disconnect&quot;">​</a></h4><p>When this option is enabled, xDrip will go through complete disconnection then reconnection of your Bluetooth device (close link, discover and connect) when connection is lost. Since this might not be efficient, it is recommended to leave it <strong>disabled</strong> so that it&#39;s maintained in memory and will only try to connect back to it as a known BLE device.</p><p><em>Collector: Classic bridge collector (<code>DexCollectionService</code>) — G4/Libre bridges, BlueReader/Atom/Tomato</em></p><div class="admonition xdripitem"><p class="admonition-title">Close GATT on BLE disconnect<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> If the Bluetooth watchdog activates often then you can try unchecking this option to see if it helps</p></div><h4 id="use-scanning" tabindex="-1">Use scanning <a class="header-anchor" href="#use-scanning" aria-label="Permalink to &quot;Use scanning&quot;">​</a></h4><p>Use scanning will perform the equivalent of Bluetooth Scan from the main menu to attempt to recover a lost connection. This is not always efficient with newer phones. Leave it initially <strong>disabled</strong> unless it proves useful.</p><p><em>Collector: Classic bridge collector (<code>DexCollectionService</code>) — G4/Libre bridges, BluKon</em></p><div class="admonition xdripitem"><p class="admonition-title">Use scanning<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Scan before connecting on xBridge and Libre Bluetooth</p></div><h4 id="use-ble-manager" tabindex="-1">Use BLE manager <a class="header-anchor" href="#use-ble-manager" aria-label="Permalink to &quot;Use BLE manager&quot;">​</a></h4><p>Use a more modern BLE manager system. Leave it <strong>disabled</strong> unless you&#39;re troubleshooting a connection issue with guidance to try it.</p><p><em>Collector: Classic bridge collector (<code>DexCollectionService</code>) — bridge-based devices</em></p><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><h4 id="trust-auto-connect" tabindex="-1">Trust auto-connect <a class="header-anchor" href="#trust-auto-connect" aria-label="Permalink to &quot;Trust auto-connect&quot;">​</a></h4><p>Trust Auto-Connect really depends on your phone. It is <strong>enabled</strong> by default. If you have a Samsung, Xiaomi, OnePlus, Oppo, Huawei or Realme you should probably disable it. If you frequently lose connection and can&#39;t manage to recover, try disabling it.</p><p><em>Collector: Classic bridge collector + OB1 Dex collector — Dexcom G5/G6/G7, bridge devices</em></p><div class="admonition xdripitem"><p class="admonition-title">Trust auto-connect<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use and trust Android Bluetooth auto connect feature</p></div><h4 id="use-background-scan" tabindex="-1">Use Background scan <a class="header-anchor" href="#use-background-scan" aria-label="Permalink to &quot;Use Background scan&quot;">​</a></h4><p>Use Background scan is a feature of newer Android versions, <strong>enabled</strong> by default. If you regularly lose connection, try disabling it.</p><p><em>Collector: Sequencer/background scan collectors (Android O+) — mainly Dexcom/BLE collectors</em></p><div class="admonition xdripitem"><p class="admonition-title">Use Background Scans<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use Android 8+ background scanning feature</p></div><h4 id="companion-bluetooth" tabindex="-1">Companion Bluetooth <a class="header-anchor" href="#companion-bluetooth" aria-label="Permalink to &quot;Companion Bluetooth&quot;">​</a></h4><p>Companion Bluetooth allows the app to work connected together with the Dex master app connected to the sensor.</p><p><em>Collector: BlueTails companion listener — Dexcom transmitters in companion/sniffer setups</em></p><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><h4 id="bluetooth-wakelocks" tabindex="-1">Bluetooth wakelocks <a class="header-anchor" href="#bluetooth-wakelocks" aria-label="Permalink to &quot;Bluetooth wakelocks&quot;">​</a></h4><p>Bluetooth wakelocks are not recommended and should be left <strong>disabled</strong>.</p><p><em>Collector: Classic collector + BLE callback paths — mostly bridge-based collectors</em></p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Older Bluetooth wakelocks which can drain extra battery but might be needed for Bluetooth reception</p></div><h4 id="xbridge-polling-mode" tabindex="-1">xBridge+ polling mode <a class="header-anchor" href="#xbridge-polling-mode" aria-label="Permalink to &quot;xBridge+ polling mode&quot;">​</a></h4><p>xBridge+ polling mode allows xDrip to send requests to the bridge. Even if it doesn&#39;t have any effect with other Bluetooth devices you can enable it if you have frequent connection loss as it will anyway keep your phone Bluetooth busy trying to connect.</p><p><em>Collector: Classic bridge collector (<code>DexCollectionService</code>) — xBridge and similar hardware</em></p><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Polling Mode<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Experimental support for xBridge+ polling feature</p></div><h4 id="always-discover-services" tabindex="-1">Always discover services <a class="header-anchor" href="#always-discover-services" aria-label="Permalink to &quot;Always discover services&quot;">​</a></h4><p>Enabled by default. Only visible with Engineering Mode enabled.</p><p><em>Collector: Classic bridge collector (<code>DexCollectionService</code>) — bridge-based BLE devices</em></p><div class="admonition xdripitem"><p class="admonition-title">Always discover services<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Probe Bluetooth services on every connect</p></div><h4 id="use-gatt-refresh" tabindex="-1">Use GATT refresh <a class="header-anchor" href="#use-gatt-refresh" aria-label="Permalink to &quot;Use GATT refresh&quot;">​</a></h4><p>Whether to use the low level GATT refresh mechanism. Enabled by default. Only visible with Engineering Mode enabled.</p><p><em>Collector: OB1 Dex collector, JamBase-style collectors — Dexcom G5/G6/G7, Medtrum</em></p><div class="admonition xdripitem"><p class="admonition-title">Use GATT refresh<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Whether to use the low level gatt refresh mechanism</p></div><h4 id="allow-blucon-unbonding" tabindex="-1">Allow BluCon unbonding <a class="header-anchor" href="#allow-blucon-unbonding" aria-label="Permalink to &quot;Allow BluCon unbonding&quot;">​</a></h4><p>Allow BluCon unbonding is only useful if you use a BluCon bridge as others don&#39;t bond with your phone. If you have frequent pairing requests with this bridge, disable it.</p><p><em>Collector: BluKon/Libre bridge path — BluKon and related Libre bridge setups</em></p><div class="admonition xdripitem"><p class="admonition-title">Allow BluCon unbonding<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Only suitable for phones which support automatic pairing</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',63)])])}const B=n(r,[["render",c]]);export{v as __pageData,B as default};
